        offset: { type: 'integer', minimum: 0, default: 0, description: 'Number of results to skip.' },
        limit: { type: 'integer', minimum: 1, maximum: 5, default: 2, description: 'Maximum number of results to return (1-5).' }
      },
      required: ['query'],
      additionalProperties: false
    }
  }];
